package id.duakelinci.dashboard;
import static id.duakelinci.dashboard.ApiModels.*;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.time.*;import java.time.format.*;import java.util.*;import org.apache.commons.csv.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;
@Component class SalesCsvParser {
 static final List<String> REQUIRED=List.of("date","invoice_no","region","branch","outlet_id","outlet_name","brand","qty_carton","gross_sales_idr","discount_idr","net_sales_idr");final int maxRows;SalesCsvParser(@Value("${sales.import.max-rows:100000}")int n){maxRows=n;}
 ParseResult parse(Path path)throws IOException{var rows=new ArrayList<SalesRecord>();var errors=new ArrayList<ValidationError>();int total=0;try(var raw=Files.newInputStream(path);var reader=new BufferedReader(new InputStreamReader(stripBom(raw),StandardCharsets.UTF_8));var csv=new CSVParser(reader,CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).setIgnoreEmptyLines(true).setTrim(true).setDuplicateHeaderMode(DuplicateHeaderMode.DISALLOW).get())){var headers=csv.getHeaderMap().keySet();var missing=REQUIRED.stream().filter(h->!headers.contains(h)).toList();if(!missing.isEmpty())errors.add(err(1,null,"MISSING_HEADER","Header wajib tidak tersedia: "+String.join(", ",missing),false));if(errors.isEmpty())for(var r:csv){total++;if(total>maxRows){errors.add(err(r.getRecordNumber()+1,null,"ROW_LIMIT_EXCEEDED","Jumlah baris melebihi batas "+maxRows,false));break;}try{rows.add(row(r));}catch(RowError e){errors.add(err(r.getRecordNumber()+1,e.column,e.code,e.getMessage(),true));}}}catch(IllegalArgumentException|UncheckedIOException e){errors.add(err(1,null,"CSV_PARSE_ERROR","CSV tidak dapat diparse: "+clean(e.getMessage()),false));}boolean structural=errors.stream().anyMatch(e->!e.rejected());if(total==0){errors.add(err(1,null,"NO_DATA","CSV tidak memiliki baris data",false));structural=true;}return new ParseResult(List.copyOf(rows),List.copyOf(errors),total,structural,sha256(path));}
 void writeValidated(Path p,List<SalesRecord> rows)throws IOException{try(var w=Files.newBufferedWriter(p,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);var csv=new CSVPrinter(w,CSVFormat.DEFAULT.builder().setHeader(REQUIRED.toArray(String[]::new)).get())){for(var r:rows)csv.printRecord(r.date(),r.invoiceNo(),r.region(),r.branch(),r.outletId(),r.outletName(),r.brand(),r.qtyCarton(),r.grossSalesIdr(),r.discountIdr(),r.netSalesIdr());}}
 private SalesRecord row(CSVRecord r){for(var k:REQUIRED)if(v(r,k).isBlank())throw new RowError(k,"REQUIRED_EMPTY",k+" wajib diisi");LocalDate d;try{d=LocalDate.parse(v(r,"date"),DateTimeFormatter.ISO_LOCAL_DATE);}catch(DateTimeParseException e){throw new RowError("date","INVALID_DATE","date harus berformat YYYY-MM-DD");}long q=num(r,"qty_carton"),g=num(r,"gross_sales_idr"),di=num(r,"discount_idr"),n=num(r,"net_sales_idr");if(q<0)throw new RowError("qty_carton","NEGATIVE_VALUE","qty_carton tidak boleh negatif");if(g<0)throw new RowError("gross_sales_idr","NEGATIVE_VALUE","gross_sales_idr tidak boleh negatif");if(di<0)throw new RowError("discount_idr","NEGATIVE_VALUE","discount_idr tidak boleh negatif");if(di>g)throw new RowError("discount_idr","DISCOUNT_EXCEEDS_GROSS","discount_idr tidak boleh melebihi gross_sales_idr");long ex;try{ex=Math.subtractExact(g,di);}catch(ArithmeticException e){throw new RowError("net_sales_idr","INTEGER_OVERFLOW","Nilai melampaui bilangan bulat 64-bit");}if(n!=ex)throw new RowError("net_sales_idr","FINANCIAL_MISMATCH","net_sales_idr harus sama dengan gross_sales_idr dikurangi discount_idr");return new SalesRecord(d,v(r,"invoice_no"),v(r,"region"),v(r,"branch"),v(r,"outlet_id"),v(r,"outlet_name"),v(r,"brand"),q,g,di,n);}
 private long num(CSVRecord r,String k){try{return Long.parseLong(v(r,k));}catch(NumberFormatException e){throw new RowError(k,"INVALID_INTEGER",k+" harus berupa bilangan bulat 64-bit");}}private String v(CSVRecord r,String k){try{return r.get(k).trim();}catch(Exception e){throw new RowError(k,"MISSING_COLUMN",k+" tidak tersedia");}}
 static InputStream stripBom(InputStream in)throws IOException{var p=new PushbackInputStream(in,3);byte[] b=p.readNBytes(3);if(!(b.length==3&&(b[0]&255)==239&&(b[1]&255)==187&&(b[2]&255)==191))p.unread(b);return p;}static String sha256(Path p)throws IOException{try{var md=MessageDigest.getInstance("SHA-256");try(var in=Files.newInputStream(p)){byte[] b=new byte[8192];for(int n;(n=in.read(b))>0;)md.update(b,0,n);}return HexFormat.of().formatHex(md.digest());}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private static ValidationError err(long r,String c,String code,String m,boolean rejected){return new ValidationError(r,c,code,clean(m),rejected);}private static String clean(String s){return s==null?"Kesalahan format CSV":s.replaceAll("[\\r\\n]+"," ");}record ParseResult(List<SalesRecord> records,List<ValidationError> errors,int totalRows,boolean structural,String checksum){}static class RowError extends RuntimeException{final String column,code;RowError(String c,String code,String m){super(m);column=c;this.code=code;}}
}
